226	// TestSubmitDuplicateCarriesOriginalDetailNotCallerEdits 区分“修改返回对象”与
227	// “提交已修改的请求”：前者不产生业务变更；原请求重提仍 duplicate 且携带最初
228	// 成功时的完整记录，而不是调用者改写后的内容；用原编号提交付款字段已合法
229	// 改变的请求一律 conflict，不新增记录、不重复扣款。
230	func TestSubmitDuplicateCarriesOriginalDetailNotCallerEdits(t *testing.T) {
231		path := newTestLedger(t, []BalanceInit{
232			{Account: "aa", Asset: "usdc", Balance: 1_000_000},
233			{Account: "bb", Asset: "usdc", Balance: 5000},
234			{Account: "aa", Asset: "eth", Balance: 100},
235		})
236		l := openOrFail(t, path)
237	
238		first := mustSettle(t, l, 30, baseScenarioPayment("p1"))
239		wantP1 := baseScenarioRecord("p1", 1)
240		assertItemResult(t, first, StatusSettled, "", wantP1)
241		balAfter := int64(1_000_000 - 1504)
242		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
243			t.Fatalf("balance after settle=%d want %d", bal, balAfter)
244		}
245	
246		// 原请求原样再次提交：duplicate，携带最初成功的完整记录，不再扣款。
247		dup := mustSettle(t, l, 30, baseScenarioPayment("p1"))
248		assertItemResult(t, dup, StatusDuplicate, reasonDuplicate, wantP1)
249		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
250			t.Fatalf("duplicate charged again: %d want %d", bal, balAfter)
251		}
252		// 公开 JSON 格式回归：duplicate 携带固定状态、说明与完整原始记录。
253		draw, err := json.Marshal(dup)
254		if err != nil {
255			t.Fatal(err)
256		}
257		for _, frag := range []string{
258			`"status":"duplicate"`, `"reason":"duplicate settlement attempt"`,
259			`"charged":1504`, `"seq":1`,
260		} {
261			if !bytes.Contains(draw, []byte(frag)) {
