263			}
264		}
265		// 成功结果与重复结果是各自独立的记录分配。
266		if first.Record == dup.Record {
267			t.Fatal("settled and duplicate results share one *Record allocation")
268		}
269	
270		// 改写首次成功结果：刚取得的 duplicate 结果不受波及。
271		corruptItemResult(&first)
