273	
274		// 再改写 duplicate 携带的记录：再次重提原请求，得到的仍是真实原始详情。
275		corruptItemResult(&dup)
276		dup2 := mustSettle(t, l, 30, baseScenarioPayment("p1"))
277		assertItemResult(t, dup2, StatusDuplicate, reasonDuplicate, wantP1)
278		if dup2.Record == dup.Record {
