283		// 不能因为调用者改过旧结果就接受新内容（目标账户/资产即使余额充足也一样，
284		// 因为重复/冲突判定先于余额）。
285		mutations := []struct {
286			name string
287			mut  func(*PaymentIntent, *int)
288		}{
289			{"amount", func(it *PaymentIntent, _ *int) { *it.Amount = 1501 }},
290			{"nonce", func(it *PaymentIntent, _ *int) { it.Nonce = 8 }},
291			{"paymaster", func(it *PaymentIntent, _ *int) { it.Paymaster = "pm-2" }},
292			{"account", func(it *PaymentIntent, _ *int) { it.Account = "bb" }},
293			{"asset", func(it *PaymentIntent, _ *int) { it.Asset = "eth" }},
294			{"fee_bps", func(_ *PaymentIntent, bps *int) { *bps = 31 }},
295		}
296		for _, tc := range mutations {
297			it := baseScenarioPayment("p1")
298			bps := 30
299			tc.mut(&it, &bps)
300			res := mustSettle(t, l, bps, it)
301			if res.Status != StatusConflict || res.Record != nil {
302				t.Fatalf("mutation %s want conflict without record, got %+v", tc.name, res)
303			}
304		}
305	
306		// 所有冲突都不新增记录、不改变原记录、不扣余额。
307		snap := mustQuery(t, l)
308		if len(snap.Settlements) != 1 || snap.Settlements[0] != wantP1 {
309			t.Fatalf("ledger settlements after conflicts:\n got %+v\nwant only %+v",
310				snap.Settlements, wantP1)
311		}
312		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
313			t.Fatalf("conflicts changed balance: %d want %d", bal, balAfter)
314		}
315	
316		// 最后原请求再次重提，仍返回 duplicate 和最初的完整记录。
317		dup3 := mustSettle(t, l, 30, baseScenarioPayment("p1"))
318		assertItemResult(t, dup3, StatusDuplicate, reasonDuplicate, wantP1)
319		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
320			t.Fatalf("duplicate after conflicts charged again: %d want %d", bal, balAfter)
321		}
322	}
323	
324	// TestSubmitSameBatchSettledAndDuplicateResultsAreIndependent 锁定同一批次内
325	// 连续提交相同合法付款时的结果隔离：首项 settled、后项 duplicate，整批只扣款
326	// 一次；两项各自持有可修改的记录副本，改动其中一项不能改变另一项，也不能
327	// 波及此前批次保留的结果、另一次调用取得的结果或账本事实。
328	func TestSubmitSameBatchSettledAndDuplicateResultsAreIndependent(t *testing.T) {
329		path := newTestLedger(t, []BalanceInit{
330			{Account: "aa", Asset: "usdc", Balance: 1_000_000},
331			{Account: "bb", Asset: "usdc", Balance: 500},
332		})
333		l := openOrFail(t, path)
334	
335		// 此前批次先成功一笔并留存结果：100@0bps => charged 100，seq=1。
336		saved0 := mustSettle(t, l, 0, intent("p0", "aa", "usdc", 100))
337		wantP0 := Record{
338			ID: "p0", Account: "aa", Paymaster: "pm", Asset: "usdc",
339			Amount: 100, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 100, Seq: 1,
340		}
341		assertItemResult(t, saved0, StatusSettled, "", wantP0)
342	
343		// 同一批次连续提交相同的合法付款：首项 settled、后项 duplicate。
344		req := baseScenarioPayment("p1")
345		rb, err := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{req, req}})
346		if err != nil {
347			t.Fatal(err)
348		}
349		if got := statuses(rb); !reflect.DeepEqual(got, []string{StatusSettled, StatusDuplicate}) {
350			t.Fatalf("statuses=%v want [settled duplicate]", got)
351		}
352		wantP1 := baseScenarioRecord("p1", 2)
353		assertItemResult(t, rb.Results[0], StatusSettled, "", wantP1)
354		assertItemResult(t, rb.Results[1], StatusDuplicate, reasonDuplicate, wantP1)
355	
356		// 整批只扣款一次：1_000_000 - 100(p0) - 1504(p1)。
357		if bal, _ := l.Balance("aa", "usdc"); bal != 1_000_000-100-1504 {
358			t.Fatalf("batch charged more than once: bal=%d want %d",
359				bal, 1_000_000-100-1504)
360		}
361		if len(mustQuery(t, l).Settlements) != 2 {
362			t.Fatalf("settlement count=%d want 2", len(mustQuery(t, l).Settlements))
363		}
364		// 同批次两项必须是各自独立的记录分配。
365		if rb.Results[0].Record == rb.Results[1].Record {
366			t.Fatal("settled and duplicate items share one *Record allocation")
367		}
368	
369		// 不同次调用取得的结果同样独立：单独再取一次 duplicate，与批内两项都不共享。
370		dupSep := mustSettle(t, l, 30, req)
371		assertItemResult(t, dupSep, StatusDuplicate, reasonDuplicate, wantP1)
372		if dupSep.Record == rb.Results[0].Record || dupSep.Record == rb.Results[1].Record {
373			t.Fatal("duplicate from a separate call shares allocation with batch results")
374		}
375	
376		// 逐项破坏性改写手里的结果：每改一项，其余尚未被改的项、此前批次保留的
377		// 结果、另一次调用取得的结果都必须保持原值。
378		wants := []Record{wantP1, wantP1}
379		wantStatus := []string{StatusSettled, StatusDuplicate}
380		corrupted := map[int]bool{}
381		for i := range rb.Results {
382			corruptItemResult(&rb.Results[i])
383			corrupted[i] = true
384			for j := range rb.Results {
385				if corrupted[j] {
386					continue // 已被自己那次改写，不要求保持原值
387				}
388				if *rb.Results[j].Record != wants[j] {
389					t.Fatalf("after corrupting item %d, item %d changed:\n got %+v\nwant %+v",
390						i, j, *rb.Results[j].Record, wants[j])
391				}
392				if rb.Results[j].Status != wantStatus[j] {
393					t.Fatalf("after corrupting item %d, item %d status=%s want %s",
394						i, j, rb.Results[j].Status, wantStatus[j])
395				}
396				wantReason := ""
397				if j == 1 {
398					wantReason = reasonDuplicate
399				}
400				if rb.Results[j].Reason != wantReason {
401					t.Fatalf("after corrupting item %d, item %d reason=%q want %q",
402						i, j, rb.Results[j].Reason, wantReason)
403				}
404			}
405			if *saved0.Record != wantP0 {
406				t.Fatalf("after corrupting item %d, earlier held result changed: %+v",
407					i, *saved0.Record)
408			}
409			assertItemResult(t, dupSep, StatusDuplicate, reasonDuplicate, wantP1)
410		}
411	
412		// 改写另一次调用的结果也不能回波到此前批次保留的结果或账本。
413		corruptItemResult(&dupSep)
414		if *saved0.Record != wantP0 {
415			t.Fatalf("earlier held result changed after corrupting separate-call result: %+v",
416				*saved0.Record)
417		}
418	
419		// 账本事实不受任何结果改写影响：两条结算记录原值，整批只扣过一次。
420		snap := mustQuery(t, l)
421		if !reflect.DeepEqual(snap.Settlements, []Record{wantP0, wantP1}) {
422			t.Fatalf("ledger settlements after result edits:\n got %+v\nwant %+v / %+v",
423				snap.Settlements, wantP0, wantP1)
424		}
425		if bal, _ := l.Balance("aa", "usdc"); bal != 1_000_000-100-1504 {
426			t.Fatalf("balance changed after result edits: %d", bal)
427		}
428	
429		// 原请求重提仍 duplicate 且详情来自账本，而非任何被改写的结果，且不再扣款。
430		again := mustSettle(t, l, 30, req)
431		assertItemResult(t, again, StatusDuplicate, reasonDuplicate, wantP1)
432		if bal, _ := l.Balance("aa", "usdc"); bal != 1_000_000-100-1504 {
433			t.Fatalf("retry charged again: bal=%d", bal)
434		}
435	}
436	
437	// TestSubmitHeldResultsStayIndependentAcrossCallsAndLaterPayments 锁定不同次
438	// 调用取得的结果彼此独立，且后续新付款追加记录不能改动此前保留且未修改的
439	// 原始结果（编号、成功序号、金额、手续费、扣款总额都保持首次成功时的值）。
440	func TestSubmitHeldResultsStayIndependentAcrossCallsAndLaterPayments(t *testing.T) {
441		path := newTestLedger(t, []BalanceInit{
442			{Account: "aa", Asset: "usdc", Balance: 2000},
443			{Account: "bb", Asset: "usdc", Balance: 500},
444		})
445		l := openOrFail(t, path)
446	
447		// p1：基础场景付款，charged 1504，aa/usdc 余 496，seq=1。
448		old1 := mustSettle(t, l, 30, baseScenarioPayment("p1"))
449		wantP1 := baseScenarioRecord("p1", 1)
450		assertItemResult(t, old1, StatusSettled, "", wantP1)
451		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
452			t.Fatalf("balance after p1=%d want 496", bal)
453		}
454	
455		// 另一次调用取得 duplicate：详情相同，但是独立分配，两者互不共享。
456		dup1 := mustSettle(t, l, 30, baseScenarioPayment("p1"))
457		assertItemResult(t, dup1, StatusDuplicate, reasonDuplicate, wantP1)
458		if old1.Record == dup1.Record {
459			t.Fatal("results from separate calls share one *Record allocation")
460		}
461		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
462			t.Fatalf("duplicate charged again: bal=%d want 496", bal)
463		}
464	
465		// 后续新付款 p2 落在另一账户，追加 seq=2（200@0bps => charged 200）。
466		old2 := mustSettle(t, l, 0, intent("p2", "bb", "usdc", 200))
467		wantP2 := Record{
468			ID: "p2", Account: "bb", Paymaster: "pm", Asset: "usdc",
469			Amount: 200, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 200, Seq: 2,
470		}
471		assertItemResult(t, old2, StatusSettled, "", wantP2)
472	
473		// 新付款追加记录不能改动此前保留的原始结果。
474		assertItemResult(t, old1, StatusSettled, "", wantP1)
475		assertItemResult(t, dup1, StatusDuplicate, reasonDuplicate, wantP1)
476	
477		// 改写新付款的结果：旧结果（含另一次调用取得的 duplicate）保持原值。
478		corruptItemResult(&old2)
479		assertItemResult(t, old1, StatusSettled, "", wantP1)
480		assertItemResult(t, dup1, StatusDuplicate, reasonDuplicate, wantP1)
481	
482		// 再改写 duplicate 结果：首次成功结果与账本都不受影响。
483		corruptItemResult(&dup1)
484		assertItemResult(t, old1, StatusSettled, "", wantP1)
485	
486		// 账本视角：两条记录按成功先后排列，金额与序号稳定；余额按真实扣款变动。
487		snap := mustQuery(t, l)
488		if !reflect.DeepEqual(snap.Settlements, []Record{wantP1, wantP2}) {
489			t.Fatalf("ledger settlements:\n got %+v\nwant %+v / %+v",
490				snap.Settlements, wantP1, wantP2)
491		}
492		if !reflect.DeepEqual(snap.Balances, []BalanceView{
493			{Account: "aa", Asset: "usdc", Balance: 496},
494			{Account: "bb", Asset: "usdc", Balance: 300},
495		}) {
496			t.Fatalf("ledger balances: %+v", snap.Balances)
497		}
498	
499		// 原请求重提仍 duplicate 且携带最初详情（seq=1、charged=1504），不再扣款。
500		again := mustSettle(t, l, 30, baseScenarioPayment("p1"))
501		assertItemResult(t, again, StatusDuplicate, reasonDuplicate, wantP1)
502		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
503			t.Fatalf("retry charged again: bal=%d want 496", bal)
504		}
505		if len(mustQuery(t, l).Settlements) != 2 {
506			t.Fatalf("retries must not add settlement records")
507		}
508	}
