1	package payflow
2	
3	import (
4		"bytes"
5		"fmt"
6		"math"
7		"os"
8		"testing"
9	)
10	
11	// 本文件为本地账本 Ledger.Submit 锁定“金额只增加一个最小单位、手续费却刚好
12	// 跨过整数界限”的大额场景。费率固定 30 基点，两个相邻金额（末尾 333/334）
13	// 的朴素乘积 amount*30 约为 1.2e20，早已超过 int64 上界（约 9.22e18），
14	// 因此任何直接相乘的实现都会溢出：要么把合法付款误判成数值溢出而拒绝，
15	// 要么把末尾数字抹掉、把两笔相邻金额当成同一金额，或把第二笔扣款总额
16	// 算成只增加一个单位。手续费的唯一规则仍是 amount*feeBps/10000 向下取整
17	// （见 charge.go 的商/余数拆分），扣款总额 = 本金 + 手续费。
18	//
19	//	金额 4000000000000000333 -> 手续费 12000000000000000，扣款 4012000000000000333
20	//	金额 4000000000000000334 -> 手续费 12000000000000001，扣款 4012000000000000335
21	//
22	// 金额、手续费与扣款总额都仍可由 int64 表示；本文件只以 Ledger.Submit 的
23	// 逐项结果、成功记录和 Query/Balance 读数为准，不设置本次扣款上限，
24	// 付款状态显式使用 pending，避免其他拒绝条件掩盖金额判断。
25	const (
26		boundaryFeeBps = 30
27	
28		boundaryAmountLo = int64(4000000000000000333)
29		boundaryAmountHi = int64(4000000000000000334)
30	
31		boundaryFeeLo = int64(12000000000000000)
32		boundaryFeeHi = int64(12000000000000001)
33	
34		boundaryChargedLo = int64(4012000000000000333)
35		boundaryChargedHi = int64(4012000000000000335)
36	)
37	
38	type boundaryCase struct {
39		name    string
40		id      string
41		amount  int64
42		fee     int64
43		charged int64
44	}
45	
46	func boundaryCases() []boundaryCase {
47		return []boundaryCase{
48			{"fee_below_boundary", "big-lo", boundaryAmountLo, boundaryFeeLo, boundaryChargedLo},
49			{"fee_crossed_boundary", "big-hi", boundaryAmountHi, boundaryFeeHi, boundaryChargedHi},
50		}
51	}
52	
53	// TestSubmitLargeFeeBoundaryNumbers 先锁定数值关系本身：相邻金额只差一个
54	// 最小单位，手续费恰差一个单位（跨过整数界限），而扣款总额相差两个单位；
55	// 三者全部在 int64 范围内，朴素乘积则会溢出。
56	func TestSubmitLargeFeeBoundaryNumbers(t *testing.T) {
57		if got := boundaryAmountHi - boundaryAmountLo; got != 1 {
58			t.Fatalf("adjacent amounts must differ by 1, got %d", got)
59		}
60		if got := boundaryFeeHi - boundaryFeeLo; got != 1 {
61			t.Fatalf("fee must step up by exactly 1 across the boundary, got %d", got)
62		}
63		// 手续费多增一个单位，因此扣款总额的增量（2）不等于金额增量（1）。
64		if got := boundaryChargedHi - boundaryChargedLo; got != 2 {
65			t.Fatalf("charged totals must differ by 2 (amount + fee steps), got %d", got)
66		}
67		for _, c := range boundaryCases() {
68			if c.charged >= math.MaxInt64 {
69				t.Fatalf("%s: charged %d must fit in int64 (max %d)", c.name, c.charged, int64(math.MaxInt64))
70			}
71			if c.fee < 0 || c.charged != c.amount+c.fee {
72				t.Fatalf("%s: charged must equal amount plus fee", c.name)
73			}
74			// 与 feeFor 的商/余数拆分结果逐项对照（amount*feeBps 本身会溢出 int64）。
75			if got := feeFor(c.amount, boundaryFeeBps); got != c.fee {
76				t.Fatalf("%s: feeFor(%d)=%d want %d", c.name, c.amount, got, c.fee)
77			}
78			fee, total, ok := chargeFor(c.amount, boundaryFeeBps)
79			if !ok || fee != c.fee || total != c.charged {
80				t.Fatalf("%s: chargeFor=(%d,%d,%v) want (%d,%d,true)", c.name, fee, total, ok, c.fee, c.charged)
81			}
82		}
83	}
84	
85	// TestSubmitLargeFeeExactBalanceSettles：余额恰好等于各自扣款总额的账本中，
86	// 两种请求都必须作为新付款 settled，余额扣到 0，历史只增加对应的一条成功
87	// 记录，记录完整保留金额末尾数字与跨过界限的手续费；关闭重开后磁盘状态一致。
88	func TestSubmitLargeFeeExactBalanceSettles(t *testing.T) {
89		for _, tc := range boundaryCases() {
90			t.Run(tc.name, func(t *testing.T) {
91				path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: tc.charged}})
92				l := openOrFail(t, path)
93	
94				res, err := l.Submit(FeeBatch{FeeBps: boundaryFeeBps, Intents: []PaymentIntent{
95					intent(tc.id, "aa", "usdc", tc.amount),
96				}})
97				if err != nil {
98					t.Fatalf("legitimate large payment must not be rejected at the batch level: %v", err)
99				}
100				if len(res.Results) != 1 {
101					t.Fatalf("want exactly 1 per-item result, got %d: %+v", len(res.Results), res.Results)
102				}
103				item := res.Results[0]
104				if item.ID != tc.id {
105					t.Fatalf("result id=%q want %q", item.ID, tc.id)
106				}
107				if item.Status != StatusSettled {
108					t.Fatalf("exact-balance payment must settle as a new payment, got status=%s reason=%q",
109						item.Status, item.Reason)
110				}
111				if item.Status == StatusInvalid {
112					t.Fatalf("large in-range payment must not be mistaken for numeric overflow")
113				}
114				if item.Reason != "" || item.Record == nil {
115					t.Fatalf("settled item must carry a success record and no reason: %+v", item)
116				}
117				rec := item.Record
118				if rec.Amount != tc.amount {
119					t.Fatalf("record amount=%d want %d (trailing digits must be preserved)", rec.Amount, tc.amount)
120				}
121				if rec.Fee != tc.fee {
122					t.Fatalf("record fee=%d want %d", rec.Fee, tc.fee)
123				}
124				if rec.Charged != tc.charged {
125					t.Fatalf("record charged=%d want %d", rec.Charged, tc.charged)
126				}
127				if rec.FeeBps != boundaryFeeBps || rec.Seq != 1 || rec.ID != tc.id ||
128					rec.Account != "aa" || rec.Asset != "usdc" {
129					t.Fatalf("record fields off: %+v", rec)
130				}
131	
132				// 查询余额为零；历史只增加对应的一条成功记录。
133				if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
134					t.Fatalf("balance after settle=%d want 0", bal)
135				}
136				snap, err := l.Query()
137				if err != nil {
138					t.Fatal(err)
139				}
140				if len(snap.Settlements) != 1 {
141					t.Fatalf("want exactly 1 settlement in history, got %+v", snap.Settlements)
142				}
143				got := snap.Settlements[0]
144				if got.ID != tc.id || got.Amount != tc.amount || got.Fee != tc.fee ||
145					got.Charged != tc.charged || got.FeeBps != boundaryFeeBps || got.Seq != 1 {
146					t.Fatalf("queried record does not preserve the exact amount/fee: %+v", got)
147				}
148				if len(snap.Balances) != 1 || snap.Balances[0].Balance != 0 {
149					t.Fatalf("queried balances after settle: %+v", snap.Balances)
150				}
151	
152				// 关闭重开：磁盘上的大额记录与零余额必须原样恢复（重放校验同样
153				// 采用商/余数手续费规则，不能把该记录判为损坏）。
154				if err := l.Close(); err != nil {
155					t.Fatal(err)
156				}
157				l2 := openOrFail(t, path)
158				if bal, _ := l2.Balance("aa", "usdc"); bal != 0 {
159					t.Fatalf("balance after reopen=%d want 0", bal)
160				}
161				snap2, _ := l2.Query()
162				if len(snap2.Settlements) != 1 {
163					t.Fatalf("after reopen want 1 settlement, got %+v", snap2.Settlements)
164				}
165				r2 := snap2.Settlements[0]
166				if r2.Amount != tc.amount || r2.Fee != tc.fee || r2.Charged != tc.charged {
167					t.Fatalf("after reopen record lost the exact figures: %+v", r2)
168				}
169			})
170		}
171	}
172	
173	// TestSubmitLargeFeeOneUnitShortIsInsufficient：余额比各自扣款总额少一个
174	// 最小单位时必须返回 insufficient_balance——付款本金本身仍小于可用余额，
175	// 拒绝的原因是计入手续费后恰好差一个单位。失败项不携带成功记录，余额与
176	// 历史保持提交前状态，账本文件逐字节不变；Submit 本身正常返回逐项结果
177	// （不是批次级错误）。
178	func TestSubmitLargeFeeOneUnitShortIsInsufficient(t *testing.T) {
179		for _, tc := range boundaryCases() {
180			t.Run(tc.name, func(t *testing.T) {
181				start := tc.charged - 1
182				path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: start}})
183				l := openOrFail(t, path)
184	
185				// 明确前置条件：本金自身仍在可用余额之内，差额完全来自手续费。
186				if tc.amount >= start {
187					t.Fatalf("test setup invalid: principal %d must be strictly below available balance %d", tc.amount, start)
188				}
189				if tc.amount+tc.fee != start+1 {
190					t.Fatalf("test setup invalid: amount+fee must exceed balance by exactly 1")
191				}
192	
193				before, err := os.ReadFile(path)
194				if err != nil {
195					t.Fatal(err)
196				}
197	
198				res, err := l.Submit(FeeBatch{FeeBps: boundaryFeeBps, Intents: []PaymentIntent{
199					intent(tc.id, "aa", "usdc", tc.amount),
200				}})
201				if err != nil {
202					t.Fatalf("insufficient balance is a per-item result, Submit must not error: %v", err)
203				}
204				if len(res.Results) != 1 {
205					t.Fatalf("want 1 per-item result, got %+v", res.Results)
206				}
207				item := res.Results[0]
208				if item.Status != StatusFunds {
209					t.Fatalf("one unit short must be insufficient_balance, got status=%s reason=%q",
210						item.Status, item.Reason)
211				}
212				if item.Reason != reasonFunds {
213					t.Fatalf("reason must clearly state insufficient balance, got %q want %q",
214						item.Reason, reasonFunds)
215				}
216				if item.Record != nil {
217					t.Fatalf("rejected item must not carry a success record: %+v", item.Record)
218				}
219	
220				// 余额与历史保持提交前状态。
221				if bal, _ := l.Balance("aa", "usdc"); bal != start {
222					t.Fatalf("balance changed after rejection: %d want %d", bal, start)
223				}
224				snap, _ := l.Query()
225				if len(snap.Settlements) != 0 {
226					t.Fatalf("rejected payment must leave no success record: %+v", snap.Settlements)
227				}
228				if len(snap.Balances) != 1 || snap.Balances[0].Balance != start {
229					t.Fatalf("queried balances changed: %+v", snap.Balances)
230				}
231	
232				// 账本文件不因这次失败发生变化（没有任何落盘）。
233				after, err := os.ReadFile(path)
234				if err != nil {
235					t.Fatal(err)
236				}
237				if !bytes.Equal(before, after) {
238					t.Fatalf("ledger file changed byte-wise after an insufficient_balance rejection")
239				}
240	
241				// 重开后仍无记录、余额不变。
242				if err := l.Close(); err != nil {
243					t.Fatal(err)
244				}
245				l2 := openOrFail(t, path)
246				if bal, _ := l2.Balance("aa", "usdc"); bal != start {
247					t.Fatalf("balance after reopen=%d want %d", bal, start)
248				}
249				if snap2, _ := l2.Query(); len(snap2.Settlements) != 0 {
250					t.Fatalf("after reopen history must stay empty: %+v", snap2.Settlements)
251				}
252			})
253		}
254	}
255	
256	// TestSubmitLargeFeeBoundaryPerItemFailure 证明余额不足在多项目批次中仍只是
257	// 逐项业务失败：合法批次正常返回逐项结果，失败项不扣余额、不留记录、不占
258	// 编号，相邻金额不会被当成同一笔付款。
259	func TestSubmitLargeFeeBoundaryPerItemFailure(t *testing.T) {
260		// 场景一：先提交手续费跨界限的金额（差两个单位，失败），再提交较小的
261		// 相邻金额（余额恰好够）。初始余额 = chargedHi-1 = chargedLo+1。
262		t.Run("short_hi_then_exact_lo", func(t *testing.T) {
263			start := boundaryChargedHi - 1 // 比 high 扣款少 1，比 low 扣款多 1
264			path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: start}})
265			l := openOrFail(t, path)
266	
267			res, err := l.Submit(FeeBatch{FeeBps: boundaryFeeBps, Intents: []PaymentIntent{
268				intent("big-hi", "aa", "usdc", boundaryAmountHi), // 计入手续费后差 1，失败
269				intent("big-lo", "aa", "usdc", boundaryAmountLo), // 前项失败不扣款，本项成功
270			}})
271			if err != nil {
272				t.Fatalf("a batch containing a failing item must still return results: %v", err)
273			}
274			want := []string{StatusFunds, StatusSettled}
275			if got := statuses(res); fmt.Sprint(got) != fmt.Sprint(want) {
276				t.Fatalf("statuses=%v want %v", got, want)
277			}
278			hi, lo := res.Results[0], res.Results[1]
279			if hi.Reason != reasonFunds || hi.Record != nil {
280				t.Fatalf("hi item must fail insufficient without a record: %+v", hi)
281			}
282			if lo.Record == nil || lo.Record.Amount != boundaryAmountLo ||
283				lo.Record.Fee != boundaryFeeLo || lo.Record.Charged != boundaryChargedLo || lo.Record.Seq != 1 {
284				t.Fatalf("lo item must settle with its exact figures: %+v", lo)
285			}
286	
287			// 余额只被成功项扣减：start - chargedLo = 1。
288			if bal, _ := l.Balance("aa", "usdc"); bal != 1 {
289				t.Fatalf("balance=%d want 1", bal)
290			}
291			snap, _ := l.Query()
292			if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "big-lo" {
293				t.Fatalf("history must contain only the settled lo item: %+v", snap.Settlements)
294			}
295	
296			// 失败的 hi 编号未被占用：再次提交仍走到余额判断（insufficient_balance），
297			// 而不是 duplicate/conflict——两项自始至终都是不同的付款请求。
298			retry, err := l.Submit(FeeBatch{FeeBps: boundaryFeeBps, Intents: []PaymentIntent{
299				intent("big-hi", "aa", "usdc", boundaryAmountHi),
300			}})
301			if err != nil {
302				t.Fatal(err)
303			}
304			r := retry.Results[0]
305			if r.Status != StatusFunds || r.Record != nil {
306				t.Fatalf("failed hi id must remain unconsumed and fail on funds again: %+v", r)
307			}
308			if bal, _ := l.Balance("aa", "usdc"); bal != 1 {
309				t.Fatalf("retry must not change balance: %d", bal)
310			}
311			if snap, _ := l.Query(); len(snap.Settlements) != 1 {
312				t.Fatalf("retry must not add history: %+v", snap.Settlements)
313			}
314	
315			// 账本文件中只留有成功的 lo 记录，失败的 hi 从未落盘。
316			raw, err := os.ReadFile(path)
317			if err != nil {
318				t.Fatal(err)
319			}
320			if bytes.Contains(raw, []byte(`"big-hi"`)) || !bytes.Contains(raw, []byte(`"big-lo"`)) {
321				t.Fatalf("ledger file must persist only big-lo:\n%s", raw)
322			}
323		})
324	
325		// 场景二：较小金额先成功把余额扣到 0，随后提交较大的相邻金额。若实现把
326		// 334 截断/抹零成 333，第二项会被识别成同一笔已成功付款而返回 duplicate；
327		// 正确行为是把它视为另一笔新付款，因余额不足返回 insufficient_balance。
328		t.Run("exact_lo_then_short_hi", func(t *testing.T) {
329			path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: boundaryChargedLo}})
330			l := openOrFail(t, path)
331	
332			res, err := l.Submit(FeeBatch{FeeBps: boundaryFeeBps, Intents: []PaymentIntent{
333				intent("big-lo", "aa", "usdc", boundaryAmountLo), // 恰好扣尽，成功
334				intent("big-hi", "aa", "usdc", boundaryAmountHi), // 相邻但不同的新付款：余额不足
335			}})
336			if err != nil {
337				t.Fatalf("per-item failure must still return a normal batch result: %v", err)
338			}
339			want := []string{StatusSettled, StatusFunds}
340			if got := statuses(res); fmt.Sprint(got) != fmt.Sprint(want) {
341				t.Fatalf("statuses=%v want %v", got, want)
342			}
343			hi := res.Results[1]
344			if hi.Reason != reasonFunds || hi.Record != nil {
345				t.Fatalf("hi item must be a distinct payment failing on funds, not a duplicate: %+v", hi)
346			}
347			if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
348				t.Fatalf("balance=%d want 0", bal)
349			}
350			snap, _ := l.Query()
351			if len(snap.Settlements) != 1 {
352				t.Fatalf("only the lo payment may enter history: %+v", snap.Settlements)
353			}
354			rec := snap.Settlements[0]
355			if rec.ID != "big-lo" || rec.Amount != boundaryAmountLo ||
356				rec.Fee != boundaryFeeLo || rec.Charged != boundaryChargedLo {
357				t.Fatalf("lo record must keep its exact trailing digits and fee: %+v", rec)
358			}
359		})
360	}
361

