388			t.Fatal(err)
389		}
390		raw, err := os.ReadFile(path)
391		if err != nil {
392			t.Fatal(err)
393		}
394		var doc signedDoc
395		if err := json.Unmarshal(raw, &doc); err != nil {
396			t.Fatalf("on-disk JSON invalid: %v\n%s", err, raw)
397		}
398		if doc.Version != 1 {
399			t.Fatalf("version=%d", doc.Version)
400		}
