406		}
407		if doc.Checksum == "" {
408			t.Fatalf("missing checksum: %s", raw)
409		}
410		if doc.Settlements[0].Fee != 0 { // 10*50/10000 = 0
411			t.Fatalf("fee on disk=%d", doc.Settlements[0].Fee)
412		}
413		// 文件必须是单个完整 JSON 文档 + 换行，无残留临时文件。
414		if !strings.HasSuffix(string(raw), "}\n") {
415			t.Fatalf("file does not end cleanly: %q", raw[len(raw)-5:])
416		}
