421		// 任一字节被篡改（即使记录与余额仍自洽）都必须被 checksum 拒绝。
422		tampered := bytes.Clone(raw)
423		tampered[10] ^= 0x01
424		tpath := filepath.Join(filepath.Dir(path), "tampered.json")
425		if err := os.WriteFile(tpath, tampered, 0o600); err != nil {
426			t.Fatal(err)
427		}
428		if _, err := Open(tpath); KindOf(err) != ErrCorrupt {
429			t.Fatalf("bit-flipped file want ErrCorrupt, got %v", err)
430		}
431	}
