459			"empty":       write("empty.json", nil),
460			"no checksum": write("nochecksum.json", []byte(`{"version":1,"initial_balances":[],"balances":[],"settlements":[]}`)),
461			"truncated":   write("trunc.json", raw[:len(raw)/2]),
462			"appended":    write("appended.json", append(bytes.Clone(raw), []byte("{}")...)),
463			"bitflip": func() string {
464				b := bytes.Clone(raw)
465				b[12] ^= 0x01
466				return write("bitflip.json", b)
467			}(),
468			"semantic edit": write("edited.json",
469				[]byte(strings.ReplaceAll(string(raw), `"balance":700`, `"balance":999`))),
470		}
471		for name, p := range cases {
472			t.Run(name, func(t *testing.T) {
473				if _, err := Open(p); KindOf(err) != ErrCorrupt {
