476			})
477		}
478	
479		// 损坏文件不能通过再次初始化“重开一本空账”。
480		if err := CreateLedger(cases["truncated"], nil); KindOf(err) != ErrExists {
481			t.Fatalf("init over corrupt file must report ErrExists, got %v", err)
482		}
483	}
