1431	// 损坏检测：退款成功顺序中的 after_seq 必须单调不减——付款历史只会追加，
1432	// 后一笔退款落账时已存在的结算不可能比前一笔退款时更少。
1433	func TestRefundAfterSeqRegressionRejected(t *testing.T) {
