1969	// symlinkedLedger 在真实目录初始化账本，再建立指向该目录的软链接，
1970	// 返回真实路径与经软链接的路径。
1971	func symlinkedLedger(t *testing.T, init []BalanceInit) (realPath, linkPath string) {
1972		t.Helper()
1973		dir := t.TempDir()
1974		realDir := filepath.Join(dir, "real")
1975		if err := os.Mkdir(realDir, 0o700); err != nil {
1976			t.Fatal(err)
1977		}
1978		linkDir := filepath.Join(dir, "link")
1979		if err := os.Symlink(realDir, linkDir); err != nil {
1980			t.Fatal(err)
1981		}
1982		realPath = filepath.Join(realDir, "ledger.json")
1983		if err := CreateLedger(realPath, init); err != nil {
1984			t.Fatalf("CreateLedger: %v", err)
1985		}
1986		return realPath, filepath.Join(linkDir, "ledger.json")
1987	}
