2000			t.Fatalf("first submit: %+v", res.Results[0])
2001		}
2002	
2003		// 经软链接路径提交完全相同的请求：幂等返回原记录，不再扣款。
2004		dup, err := lLink.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p1", "aa", "usdc", 60)}})
2005		if err != nil {
2006			t.Fatal(err)
