2013		// 同一编号修改金额或费率：冲突，保留原记录。
2014		modified := intent("p1", "aa", "usdc", 61)
2015		conf, err := lLink.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{modified}})
2016		if err != nil {
2017			t.Fatal(err)
