2019		if conf.Results[0].Status != StatusConflict {
2020			t.Fatalf("want conflict, got %+v", conf.Results[0])
2021		}
2022		confFee, err := lReal.Submit(FeeBatch{FeeBps: 10, Intents: []PaymentIntent{intent("p1", "aa", "usdc", 60)}})
2023		if err != nil {
2024			t.Fatal(err)
2025		}
2026		if confFee.Results[0].Status != StatusConflict {
2027			t.Fatalf("fee change: want conflict, got %+v", confFee.Results[0])
2028		}
2029	
2030		// 两个路径查询到相同的余额与历史。
2031		for name, l := range map[string]*Ledger{"real": lReal, "link": lLink} {
2032			bal, err := l.Balance("aa", "usdc")
2033			if err != nil {
2034				t.Fatal(err)
2035			}
