12	// 执行任何意图之前整批拒绝——即使第一个意图本可以成功，也不得留下扣款或成功
13	// 记录。这与逐项业务失败（金额为 0 等语义非法值）严格区分：后者退出 0、
14	// 按输入顺序逐项给出结果，前项照常扣款落账。
15	//
16	// 两个提交入口（标准输入与 -f/--file 文件）必须遵守完全相同的规则。
17	
18	// 合法的新付款 p1：费率 30 基点、金额 1500 -> 手续费 4、扣款总额 1504。
19	const atomicValidP1Batch = `{"fee_bps":30,"intents":[
20	  {"id":"p1","account":"aa","paymaster":"pm-1","asset":"usdc","amount":1500,"nonce":1,"state":"pending"}
21	]}`
22	
23	// 批次级非法输入一：第一项是能够成功的合法 p1，后一项的 amount 写成 JSON
24	// 字符串——encoding/json 解码整个批次时即失败，任何意图都不得开始执行。
25	const atomicStringAmountBatch = `{"fee_bps":30,"intents":[
26	  {"id":"p1","account":"aa","paymaster":"pm-1","asset":"usdc","amount":1500,"nonce":1,"state":"pending"},
27	  {"id":"p2","account":"aa","asset":"usdc","amount":"900"}
28	]}`
29	
30	// 批次级非法输入二：批次本身完整合法，但结尾紧接着第二个 JSON 文档。
31	const atomicTrailingDocBatch = atomicValidP1Batch + `{"fee_bps":0,"intents":[]}`
32	
33	// setupAtomicLedger 准备一个已有成功付款与退款历史、当前余额回到 2000 的账本：
34	// h1（seq=1，amount 500、手续费 1、charged 501）已由 r1 全额退款。
35	// p1 因此是全新编号；新的成功付款序号必须紧接历史为 2，不能空缺或重复。
36	// 返回账本路径与提交前的账本文件字节（用于断言文件逐字节不变）。
37	func setupAtomicLedger(t *testing.T) (string, []byte) {
38		t.Helper()
39		ledgerPath := t.TempDir() + "/ledger.json"
40		if r := runCLIWith(t, []string{"init", "-l", ledgerPath},
41			`{"balances":[{"account":"aa","asset":"usdc","balance":2000}]}`); r.code != 0 {
42			t.Fatalf("init: %s", r.err)
43		}
44		if r := runCLIWith(t, []string{"submit", "-l", ledgerPath},
45			`{"fee_bps":30,"intents":[
46			  {"id":"h1","account":"aa","paymaster":"pm-0","asset":"usdc","amount":500,"nonce":7}
47			]}`); r.code != 0 {
48			t.Fatalf("seed payment: %s", r.err)
49		}
50		if r := runCLIWith(t, []string{"refund", "-l", ledgerPath},
51			`{"refunds":[{"id":"r1","settlement_id":"h1","reason":"prior history"}]}`); r.code != 0 {
52			t.Fatalf("seed refund: %s", r.err)
53		}
54		baseline, err := os.ReadFile(ledgerPath)
55		if err != nil {
56			t.Fatal(err)
57		}
58		return ledgerPath, baseline
59	}
